<script setup lang="ts">
import {computed,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import PageShell from '../PageShell.vue'
import CaptchaInput from '../CaptchaInput.vue'
import {api} from '../api'
import {usePage} from '../page'
import {dateText} from '../commerce'
type Ticket={id:number;title:string;username:string;priority:string;status:string;updated_at:string}
type Thread={id:number;title:string;priority:string;status:string;messages:{id:number;content:string;sender_is_staff:boolean;created_at:string}[];total:number}
const staff=location.pathname==='/admin/tickets',prefix=staff?'admin/tickets':'tickets'
const rows=ref<Ticket[]>([]),page=ref(1),total=ref(0),captchaMode=ref('off'),creating=ref(false),threadOpen=ref(false),detail=ref<Thread|null>(null),messagePage=ref(1),reply=ref(''),loadingThread=ref(false)
const form=ref({title:'',content:'',priority:'medium'}),captcha=ref({id:'',answer:''}),captchaInput=ref<{refresh():Promise<void>}>()
const states:Record<string,string>={waiting_staff:'等待客服',waiting_user:'等待用户',closed:'已关闭'},priorities:Record<string,string>={low:'低',medium:'中',high:'高'}
const {me,loading,error,busy,run,refresh}=usePage(async()=>{const data=await api<{items:Ticket[];total:number}>(prefix+'?page='+page.value);rows.value=data.items;total.value=data.total;if(!staff)captchaMode.value=(await api<{captcha_mode:string}>('tickets/config')).captcha_mode;if(threadOpen.value&&detail.value)await loadThread(detail.value.id)},{admin:staff,interval:10000})
const threadClosed=computed(()=>detail.value?.status==='closed')
function create(){form.value={title:'',content:'',priority:'medium'};captcha.value={id:'',answer:''};creating.value=true}
async function submit(){await run(async()=>{try{const data=await api<{id:number}>('tickets','POST',{...form.value,captcha_id:captcha.value.id,captcha:captcha.value.answer});creating.value=false;page.value=1;await refresh();await openThread(data.id);ElMessage.success('工单已提交')}catch(e){await captchaInput.value?.refresh();throw e}})}
async function loadThread(id:number){detail.value=await api<Thread>(`${prefix}/${id}?page=${messagePage.value}`)}
async function openThread(id:number){loadingThread.value=true;try{messagePage.value=1;reply.value='';await loadThread(id);if(detail.value!.total>100){messagePage.value=Math.ceil(detail.value!.total/100);await loadThread(id)}threadOpen.value=true}catch(e){ElMessage.error((e as Error).message)}finally{loadingThread.value=false}}
async function send(){if(!detail.value)return;await run(async()=>{await api(`${prefix}/${detail.value!.id}/messages`,'POST',{content:reply.value});reply.value='';messagePage.value=Math.ceil((detail.value!.total+1)/100);await loadThread(detail.value!.id);await refresh()})}
async function changeStatus(){if(!detail.value)return;const close=!threadClosed.value;try{if(close)await ElMessageBox.confirm('关闭此工单？后续可重新打开。','关闭工单',{confirmButtonText:'关闭',cancelButtonText:'取消'});await run(async()=>{await api(`${prefix}/${detail.value!.id}/status`,'PUT',{status:close?'closed':'open'});await loadThread(detail.value!.id);await refresh()})}catch{/* cancellation */}}
</script>
<template><PageShell :me="me" :loading="loading" :error="error" active="tickets" :admin="staff"><section class="surface"><div class="section-header"><strong>{{staff?'工单管理':'我的工单'}}</strong><el-button v-if="!staff" type="primary" @click="create">发起工单</el-button><el-button @click="refresh">刷新</el-button></div><div class="section-body"><el-table :data="rows" empty-text="暂无工单"><el-table-column label="标题" min-width="220"><template #default="{row}"><el-button link type="primary" :disabled="loadingThread" @click="openThread(row.id)">#{{row.id}} · {{row.title}}</el-button></template></el-table-column><el-table-column v-if="staff" prop="username" label="用户" min-width="170"/><el-table-column label="优先级" width="90"><template #default="{row}"><span :class="['priority-label',row.priority]">{{priorities[row.priority]}}</span></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="最近更新" min-width="180"><template #default="{row}">{{dateText(row.updated_at)}}</template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="refresh" class="user-pagination"/></div></section><el-dialog v-model="creating" title="发起工单" width="620px" class="managed-form-dialog" destroy-on-close><el-form label-position="top" @submit.prevent="submit"><el-form-item label="标题"><el-input v-model="form.title" maxlength="128"/></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option label="低" value="low"/><el-option label="中" value="medium"/><el-option label="高" value="high"/></el-select></el-form-item><el-form-item label="问题描述"><el-input v-model="form.content" type="textarea" :rows="7" maxlength="5000" show-word-limit placeholder="请描述遇到的问题"/></el-form-item><CaptchaInput ref="captchaInput" v-model="captcha" endpoint="tickets/captcha" :mode="captchaMode"/></el-form><template #footer><el-button @click="creating=false">取消</el-button><el-button type="primary" :loading="busy" @click="submit">提交工单</el-button></template></el-dialog><el-dialog v-model="threadOpen" :title="detail?.title||'工单'" width="760px" class="managed-form-dialog"><template v-if="detail"><div class="thread-heading"><span :class="['priority-label',detail.priority]">{{priorities[detail.priority]}}优先级</span><span>{{states[detail.status]}}</span><el-button size="small" :loading="busy" @click="changeStatus">{{threadClosed?'重新打开':'关闭工单'}}</el-button></div><div class="ticket-thread"><article v-for="message in detail.messages" :key="message.id" :class="['ticket-message',{staff:message.sender_is_staff}]"><div class="message-meta"><strong>{{message.sender_is_staff?'客服':'用户'}}</strong><time>{{dateText(message.created_at)}}</time></div><p>{{message.content}}</p></article></div><el-pagination v-if="detail.total>100" v-model:current-page="messagePage" :page-size="100" :total="detail.total" layout="prev,pager,next" @current-change="loadThread(detail.id)"/><el-input v-if="!threadClosed" v-model="reply" type="textarea" :rows="4" maxlength="5000" show-word-limit placeholder="输入回复内容"/><p v-else class="field-tip">工单已关闭，需要继续沟通时可重新打开。</p></template><template #footer><el-button @click="threadOpen=false">返回列表</el-button><el-button v-if="!threadClosed" type="primary" :loading="busy" :disabled="!reply.trim()" @click="send">发送回复</el-button></template></el-dialog></PageShell></template>
<style scoped>.priority-label{display:inline-block;padding:4px 10px;border-radius:9px;font-size:13px;border:1px solid transparent}.priority-label.low{background:rgba(109,184,255,.17);color:#83baff;border-color:rgba(109,184,255,.3)}.priority-label.medium{background:rgba(245,210,103,.16);color:#e6c773;border-color:rgba(245,210,103,.3)}.priority-label.high{background:rgba(248,137,151,.16);color:#ef99a2;border-color:rgba(248,137,151,.3)}.thread-heading{display:flex;align-items:center;gap:14px;margin-bottom:16px;flex-wrap:wrap}.thread-heading button{margin-left:auto}.ticket-thread{max-height:50vh;overflow:auto;margin-bottom:18px}.ticket-message{padding:16px;margin:10px 0;border-radius:16px;background:var(--el-fill-color-light)}.ticket-message.staff{border-left:3px solid var(--el-color-primary)}.ticket-message p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;margin-bottom:0}.message-meta{display:flex;justify-content:space-between;gap:16px;color:var(--el-text-color-secondary);font-size:13px}:global(html:not(.dark)) .priority-label.low{color:#326fb0;background:#e9f4ff}:global(html:not(.dark)) .priority-label.medium{color:#957223;background:#fff7df}:global(html:not(.dark)) .priority-label.high{color:#b44e60;background:#ffedf0}</style>
